    auto key=std::pair{ability,level};if(auto found=deathPassives_.find(key);found!=deathPassives_.end())return found->second?&*found->second:nullptr;auto& data=definitions();auto code=data.field(ability,"AbilityData","code",ObjectData::name(ability));std::optional<DeathPassiveInfo> result;
