void ScriptSession::initializeDeathRestart(UnitState& u){if(u.illusion || u.removing || u.phoenixCycle || number(u.life)<=0)return;for(auto [ability,level]:u.abilities)if(level>0)if(auto d=deathPassiveInfo(ability,unsigned(level));d && d->kind==DeathPassiveKind::Phoenix && u.type==d->eggType){u.phoenixCycle=PhoenixCycle{*d,d->delay};deathRestartActors_.insert(u.handle);return;}}
void ScriptSession::clearDeathRestart(UnitState& u){if(u.rebirth){for(auto effect:u.rebirth->visuals)destroyEffect(effect);u.rebirth.reset();}u.phoenixCycle.reset();deathRestartActors_.erase(u.handle);}
